-- 模块:表格生成器/数据/trap：tools/build_tablegen_data.py 由 [[陷阱]] 页里的随机表拆成（别手改）。格式见脚本说明。
return [=====[{"陷阱":{"sec":{},"tab":{"触发器":[[null,null,"秘法眼","视觉线 (无限距离)","+20"],[null,null,"鹰眼术","一个预先选定的位置","+15"],[null,null,"真知术","视觉线 (上限120尺)","+30"]],"表：陷阱CR修正":[[null,null,"15及以下","–1"],[16,20,"–"],[21,25,"+1"],[26,29,"+2"],[null,null,"30及以上","+3"],[null,null,"15及以下","–1"],[16,20,"–"],[21,25,"+1"],[26,29,"+2"],[null,null,"30及以上","+3"],[null,null,"15及以下","–1"],[16,20,"–"],[21,25,"+1"],[26,29,"+2"],[null,null,"30及以上","+3"],[null,null,"+0及以下","–2"],[null,null,"+1到+5","–1"],[null,null,"+6到+10","–"],[null,null,"+11到+15","+1"],[null,null,"+16到+20","+2"],[null,null,"接触攻击","+1"],[null,null,"平均伤害","每10点平均伤害+1"],[null,null,"炼金物品装置","所模拟法术环位"],[null,null,"自动复位","+1"],[null,null,"内装液体","+5"],[null,null,"复数目标 (非伤害)","+1"],[null,null,"永不落空","+2"],[null,null,"接近型或视觉型触发器","+1"],[null,null,"最高环位法术效果","+法术环位"],[null,null,"造成伤害法术效果","每10点平均伤害+1"],[null,null,"黑蛇毒","+1"],[null,null,"黑莲汁","+8"],[null,null,"血根草","+1"],[null,null,"青嘶泣","+1"],[null,null,"焦引熏烟","+6"],[null,null,"死刃夜露","+5"],[null,null,"龙胆汁","+6"],[null,null,"巨型黄蜂毒","+3"],[null,null,"绿血油","+1"],[null,null,"狂雾","+4"],[null,null,"大型蝎子毒","+3"],[null,null,"烈赤根糊","+3"],[null,null,"中型蜘蛛毒","+2"],[null,null,"耐萨瑞毒","+4"],[null,null,"紫虫毒","+4"],[null,null,"幻叶余烬","+3"],[null,null,"暗菁华露","+3"],[null,null,"小蜈蚣毒","+1"],[null,null,"贴内根","+5"],[null,null,"魔地尘","+3"],[null,null,"翼龙毒","+5"]],"表：魔法装置陷阱成本修正":[[null,null,"触发器中使用‘警报术’","–"],[null,null,"每个使用的法术","+ 50gp×CL×法术环位"],[null,null,"法术材料成分","+ 法术材料成分"],[null,null,"每个使用的法术","+ 500gp×CL×法术环位"],[null,null,"法术材料成分","+ 法术材料成分×100"]],"表：工艺 (陷阱) DC":[[1,5,"20"],[6,10,"25"],[11,15,"30"],[null,null,"16 +","35"],[null,null,"接近型触发器","+5"],[null,null,"自动复位","+5"]]},"defs":{"机械陷阱":"只需选择你希望该陷阱所具有的要素，并将这些要素的陷阱CR修正 (见对应表格) 加上去得到陷阱最终的CR。从该CR可以得出要制造该陷阱所必须达到的工艺 (陷阱) 检定DC。","魔法陷阱":"和机械陷阱一样，决定你想要的陷阱要素和决定陷阱CR (见对应表格)。如果PC想设计制造一个魔法陷阱，他必须具有“制造奇物”专长。另外，他必须有能力施展该陷阱所需的所有魔法，如果做不到，那么他必须雇一个NPC来为他施展那些法术。","位置型":"位置触发器会在有人站在特定区域时启动陷阱。","接近型":"<p>这种触发器会在生物靠近到一定距离内时启动陷阱。接近型触发器和位置型触发器不同，生物不必站在特定位置就会触发它。飞行中的生物可以触发一个使用接近型触发器的陷阱，但是不会触发使用位置型触发器的陷阱。机械接近型触发器对空气微小的扰动非常敏感。这使得它只能用在墓穴一类的地方，因为那里空气异常稳定。</p><p>有些魔法装置陷阱用特别的接近型触发器来保证只被接近的特定种类生物触发。例如，法术[[侦测善良]]可以用在一个邪恶祭坛上当作接近型触发器，只有某个善良阵营的人靠近到足够近时才会触发相关的陷阱。</p>","声响型":"这类触发器会在侦测到任何声音时触发魔法陷阱。一个声响型触发器的工作方式就像一只耳朵，并且在察觉检定上有+15加值。成功的隐匿检定、[[沉默术]]或者其他类似可以阻挡听力的方法都可以避开它。制造使用声响型触发器的陷阱需要在制造期间施展‘锐耳术’。","视觉型":"<p>这类触发器工作方法类似真正的眼睛，只要它“看见”某些东西就会触发陷阱。制造带有视觉型触发器的陷阱需要在制造期间施展[[秘法眼]]、[[鹰眼术]]或者[[真知术]]。该陷阱获得的视界和察觉加值基于采用的法术，见下表。</p><p>如果你想让这个陷阱能在黑暗中“看”，你必须选择‘真知术’，或者给陷阱附加一个‘黑暗视觉’法术 (‘黑暗视觉’给陷阱提供的黑暗视觉距离为60尺)。如果有[[隐形]]、[[易容]]或者幻觉能够愚弄陷阱所使用的法术，那么它们同样也能愚弄这个视觉型触发器。</p>","接触型":"接触型触发器会在被触动的时候触发陷阱，它是一种最简单的触发器。这种触发器可以被物理性的附加在某个能造成伤害的机械装置上，也可以并非如此。你也可以在陷阱上附加一个‘警报术’并将法术效果区域减少到只覆盖触发器所处地点，用这种方式可以制造一个魔法接触型触发器。","定时型":"这种触发器能以特定时间为周期来触发陷阱。","法术型":"所有的法术陷阱都有这类触发器。对应法术的说明解释了该法术型触发器对应陷阱的触发器条件。","无法复位":"除非完全重建这个陷阱，否则不可能多次触发这个陷阱。法术陷阱都有“无法复位”这一要素。","修复":"要让这个陷阱再次运作，你必须修复它。修复机械陷阱需要进行DC等同于构造它的工艺 (陷阱) 检定。修复成本为陷阱原始市价的1/5。要计算修复陷阱的耗时，使用与制作该陷阱相同的时间，但原材料成本部分将采用修复成本来取代。","手动":"要复位该陷阱需要有人将它的部件放回原位。大部分机械陷阱所具有的复位要素都是这类。","自动":"陷阱本身能复位自己，有可能是立刻复位，也有可能是在一段时间间隔后。","锁":"一个使用锁的开关需要DC 30的解除装置检定来打开。","隐藏开关":"一个隐藏的开关需要DC 25的察觉检定来找到它。","隐藏锁":"隐藏锁结合了之前两项特性，需要DC 25的察觉检定来找到它，并用DC 30的解除装置检定来打开它。","远程攻击型陷阱":"这些陷阱在被触发的时候发射飞标、箭、矛，或者其他类似武器。由建造者设定其攻击加值。远程攻击型陷阱可以配备类似高力量强力复合弓的效果，这样可以让其伤害得到等同于其力量值的加值。这些陷阱的伤害和其弹药正常的伤害相同。如果该陷阱建造时带有高力量值，那么还要将相应的加值加在伤害上。","近战攻击型陷阱":"<p>这些陷阱主要作用是当障碍物，例如墙上出现的利刃或者从天花板上掉下来的大石块。依然是由建造者设定其攻击加值。这些陷阱的伤害如同它们“装备”了近战武器一样。在落石陷阱的情况中，你可以设定任何你喜欢的钝击伤害值，不过要记住是由谁将那些石块放回原位来复位陷阱。</p><p>近战攻击型陷阱建造时可以将制作加值加在它的伤害检定上，如同该陷阱自身有高力量值一样。</p>","法术陷阱":"法术陷阱会产生法术效果。和所有法术一样，法术陷阱允许进行一次DC为 {10+法术环位+相关属性修正} 的豁免。","魔法装置陷阱":"这些陷阱会产生建造期间加入的任何法术的效果，见对应情况说明。如果魔法装置陷阱中的法术允许进行豁免，那么它的豁免DC为 {10+法术环位×1.5}。有些法术以攻击检定代替豁免。","特殊":"有些具有杂项特性的陷阱会造成其他的特殊效果，例如在水陷阱中溺水，或者中毒造成的[[属性伤害]]。豁免和伤害根据毒素的种类而定，或者由建造者设定，见对应说明。","陷坑钉刺":"陷坑底部的钉刺视作[[匕首]]，每颗钉刺都具有+10攻击加值。每颗钉刺的伤害加值为每10尺陷坑深度+1 (最多+5)。落进陷坑里的人会被1d4颗钉刺攻击。陷坑钉刺不会增加陷阱的平均伤害 (见之后的平均伤害)。这种伤害是累加在跌落本身造成的任何伤害之上，并且上述数据只体现了最常见的钉刺——某些陷阱底部会有远远更为凶狠的钉刺。钉刺的平均伤害将被加至陷阱伤害 (见下文的平均伤害)。","陷坑底部":"如果在陷坑底部有钉刺以外的东西，最好是视其为另外一个独立的陷阱 (见之后的多重陷阱)，该陷阱有一个位置型触发器，会被很大的冲击所触发，例如坠落中的人。","[[接触攻击]]":"那些攻击时只需作一次成功接触攻击 (近战或远程) 的陷阱应用此特性。","炼金物品":"机械陷阱也可以混合炼金术装置或其他特别物品，例如[[绊足包]]、[[炽火胶]]、[[爆雷石]]，或者其他类似物品。有些这类物品模拟了法术效果。如果该物品模拟了法术效果，它会增加陷阱的CR，详见对应表格。","毒气":"毒气陷阱的危险性在于它所散发的吸入性毒素。使用毒气的陷阱通常具有“永不落空”和“延迟发动”的特性。","液体":"任何会造成淹溺危险的陷阱都属于这一类。使用液体的陷阱通常具有“永不落空”和“延迟发动”的特性。","多重目标":"具有这项特性的陷阱能影响超过一位角色。","永不落空":"当地下城的整堵墙压向你时，你的快速反应对你毫无帮助，因为这堵墙不可能避开。具有这项特性的陷阱没有攻击加值或用来避开的豁免，但是它具有延迟发动值。大部分使用液体和毒气的陷阱都具有“永不落空”的特性。","延迟发动":"延迟发动指的是陷阱被触动时和它造成伤害时之间的时间差。“永不落空”的陷阱总是具有延迟发动值","毒素":"用毒的陷阱比对应无毒的陷阱更加致命，因此它们相对来说有更高的CR。要决定给定毒素的CR修正，请查阅对应表格。陷阱上只能使用伤口、接触、以及吸入性的毒素，摄入性毒素不能用在陷阱上。某些陷阱仅仅能造成毒素的伤害。另外一些陷阱则可以同时造成远程或近战伤害。","平均伤害":"<p>如果陷阱 (机械或者魔法) 能造成生命值伤害，那么计算一次成功命中所能造成的平均伤害，并将其取近似到最接近的10的倍数。若该陷阱被设计为命中多于1个目标，将此数值乘以2。若该陷阱被设计为在一定轮数内造成伤害，将此数值乘以陷阱将生效的轮数 (若持续时间可变则取平均值)。用此数值来调整陷阱的挑战等级，见对应表格中的说明。毒素造成的伤害不计入此数值，但是钉刺和多次攻击所造成的额外伤害要记入平均伤害。</p><p>对于魔法陷阱来说，只能有一种修正能影响其CR——该陷阱使用的最高环法术的环位或者平均伤害值，取其高者。</p>","多重陷阱":"如果一个陷阱实际上是两个及以上影响相同区域的相互联系的陷阱，单独计算它们的CR。","多重互相依赖的陷阱":"如果一个陷阱取决于其他陷阱的成功 (即如果你没有被第一道陷阱伤害，你就可以完全避开第二道陷阱)，那么角色可以在搞定第一道陷阱后获得所有陷阱的奖励XP，无论其后的是否被触发。","多重不互相依赖的陷阱":"如果两个或者更多的陷阱独立运作 (即陷阱之间不会相互触发)，那么角色只能获得被搞定的陷阱的奖励XP。"}},"poison":[["黑蛇毒",1,120],["黑莲汁",8,4500],["血根草",1,100],["青嘶泣",1,120],["焦引熏烟",6,2100],["死刃夜露",5,1800],["龙胆汁",6,1500],["巨型黄蜂毒",3,210],["绿血油",1,100],["狂雾",4,1500],["大型蝎子毒",3,200],["烈赤根糊",3,250],["中型蜘蛛毒",2,150],["耐萨瑞毒",4,650],["紫虫毒",4,700],["幻叶余烬",3,300],["暗菁华露",3,250],["小蜈蚣毒",1,90],["贴内根",5,400],["魔地尘",3,1000],["翼龙毒",5,3000]]}]=====]